#include <algorithm>
using namespace std;
struct Muchie { int u, v, c; };
bool cmp(Muchie a, Muchie b) { return a.c < b.c; }
int t[1005];
int rad(int x) {
    if (t[x] == x) return x;
    return t[x] = rad(t[x]);
}
int main() {
    int n, m;
    cin >> n >> m;
    vector<Muchie> e(m);
    for (int i = 0; i < m; i++) cin >> e[i].u >> e[i].v >> e[i].c;
    sort(e.begin(), e.end(), cmp);
    for (int i = 1; i <= n; i++) t[i] = i;
    long long cost = 0;
    for (Muchie mch : e) {
        int ru = rad(mch.u), rv = rad(mch.v);
        if (ru != rv) {
            t[ru] = rv;
            cost += mch.c;
        }
    }
    cout << cost;
    return 0;
}

