#include <fstream>
using namespace std;
ifstream fin("birocratie.in");
ofstream fout("birocratie.out");
const long long INF = 1e18;
int n;
long long b[1005][1005], f[1005][1005];
long long e[1005]; // e[i] = câștigul maxim cu care se intră în celula (i, d - i)
int main() {
    fin >> n;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++) fin >> b[i][j];
    // pe o diagonală i + j = d mutările (i+1, j-1) și (i-1, j+1) rămân pe diagonală,
    // iar (i, j+1) și (i+1, j) trec pe diagonala următoare
    for (int d = 2; d <= 2 * n; d++) {
        int lo = max(1, d - n), hi = min(n, d - 1);
        for (int i = lo; i <= hi; i++) {
            int j = d - i;
            if (d == 2) e[i] = 0;
            else {
                e[i] = -INF;
                if (j > 1) e[i] = max(e[i], f[i][j - 1]);
                if (i > 1) e[i] = max(e[i], f[i - 1][j]);
            }
        }
        // se intră în celula e și se merge de-a lungul diagonalei până la i, într-un singur sens
        long long best = -INF;
        for (int i = lo; i <= hi; i++) { // în jos-stânga (i crește)
            best = max(best, e[i]) + b[i][d - i];
            f[i][d - i] = best;
        }
        best = -INF;
        for (int i = hi; i >= lo; i--) { // în sus-dreapta (i scade)
            best = max(best, e[i]) + b[i][d - i];
            f[i][d - i] = max(f[i][d - i], best);
        }
    }
    fout << f[n][n];
    return 0;
}

93.context:
Boris vizitează o clădire de birouri care formează un caroiaj pătratic N × N; biroul de pe linia i și coloana j este (i, j). Boris intră prin biroul (1, 1) și își termină traseul în biroul (N, N). Din biroul (i, j) se poate muta în:
• (i, j + 1), la dreapta, pe același rând;
• (i + 1, j), în jos, pe aceeași coloană;
• (i + 1, j − 1) sau (i − 1, j + 1), pe diagonală.
Boris nu intră niciodată de două ori în același birou.

În fiecare birou vizitat, Boris încheie un contract în valoare de B(i, j) lei: dacă B(i, j) > 0, primește banii, iar dacă B(i, j) < 0, plătește −B(i, j) lei.

