bool art[10001];
void dfs(int u, int p) {
    tin[u] = low[u] = ++timp;
    int fii = 0;
    for (int v : g[u]) {
        if (v == p) continue;
        if (tin[v]) low[u] = min(low[u], tin[v]);
        else {
            dfs(v, u);
            low[u] = min(low[u], low[v]);
            if (p != 0 && low[v] >= tin[u]) art[u] = true;
            fii++;
        }
    }
    if (p == 0 && fii > 1) art[u] = true;
}
