        g[v].push_back(u);
    }
    dfs(1, 0);
    bool are = false;
    for (int i = 1; i <= n; i++)
        if (art[i]) {
            cout << i << " ";
            are = true;
        }
    if (!are) cout << 0;
    return 0;
}

