using namespace std;
const int MOD = 1000000007;
vector<pair<int, int>> g[100001];
long long d[100001], cnt[100001];
int main() {
    int n, m, u, v, c;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        cin >> u >> v >> c;
        g[u].push_back({v, c});
        g[v].push_back({u, c});
    }
    for (int i = 1; i <= n; i++) d[i] = -1;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> q;
    d[1] = 0;
    cnt[1] = 1;
    q.push({0, 1});
    while (!q.empty()) {
        auto [du, a] = q.top();
        q.pop();
        if (du > d[a]) continue;
        for (auto [b, w] : g[a]) {
            if (d[b] == -1 || du + w < d[b]) {
                d[b] = du + w;
                cnt[b] = cnt[a];
                q.push({d[b], b});
            } else if (du + w == d[b]) cnt[b] = (cnt[b] + cnt[a]) % MOD;
        }
    }
    if (d[n] == -1) cout << -1;
    else cout << d[n] << " " << cnt[n];
    return 0;
}

