#include <iostream>
#include <algorithm>
using namespace std;
struct M { int u, v; long long c; };
M e[200000];
int t[100001];
int rad(int x) {
    while (t[x] != x) x = t[x] = t[t[x]];
    return x;
}
bool cmp(const M& a, const M& b) { return a.c < b.c; }
int main() {
    int n, m, k, comp;
    cin >> n >> m >> k;
    for (int i = 0; i < m; i++) cin >> e[i].u >> e[i].v >> e[i].c;
    for (int i = 1; i <= n; i++) t[i] = i;
    comp = n;
    for (int i = 0; i < k; i++) {
        int a = rad(e[i].u), b = rad(e[i].v);
        if (a != b) {
            t[a] = b;
            comp--;
        }
    }
    sort(e + k, e + m, cmp);
    long long cost = 0;
    for (int i = k; i < m; i++) {
        int a = rad(e[i].u), b = rad(e[i].v);
        if (a != b) {
            t[a] = b;
            comp--;
            cost += e[i].c;
        }
    }
    cout << (comp == 1 ? cost : -1);
    return 0;
}

