}

#include <iostream>
#include <string>
using namespace std;
short L[2002][2002];
short na[2002][26], nb[2002][26];
int main() {
    string a, b;
    cin >> a >> b;
    int n = a.size(), m = b.size();
    for (int i = n - 1; i >= 0; i--)
        for (int j = m - 1; j >= 0; j--)
            L[i][j] = (a[i] == b[j]) ? L[i + 1][j + 1] + 1 : max(L[i + 1][j], L[i][j + 1]);
    for (int c = 0; c < 26; c++) na[n][c] = nb[m][c] = -1;
    for (int i = n - 1; i >= 0; i--)
        for (int c = 0; c < 26; c++) na[i][c] = (a[i] - 'a' == c) ? i : na[i + 1][c];
    for (int j = m - 1; j >= 0; j--)
        for (int c = 0; c < 26; c++) nb[j][c] = (b[j] - 'a' == c) ? j : nb[j + 1][c];
    int rest = L[0][0], i = 0, j = 0;
    cout << rest << "\n";
    string r;
    while (rest > 0) {
        for (int c = 0; c < 26; c++) {
            int p = na[i][c], q = nb[j][c];
            if (p != -1 && q != -1 && L[p + 1][q + 1] == rest - 1) {
                r.push_back('a' + c);
                i = p + 1;
                j = q + 1;
                rest--;
                break;
            }
        }
    }
    cout << r;
    return 0;
}

