#include <iostream>
#include <stack>
using namespace std;
int h[1002];
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m, x;
    long long best = 0;
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> x;
            h[j] = x ? h[j] + 1 : 0;
        }
        stack<int> s;
        for (int j = 0; j <= m; j++) {
            int cur = (j == m) ? 0 : h[j];
            while (!s.empty() && h[s.top()] >= cur) {
                int top = s.top();
                s.pop();
                int st = s.empty() ? -1 : s.top();
                long long a = (long long)h[top] * (j - st - 1);
                if (a > best) best = a;
            }
            s.push(j);
        }
    }
    cout << best;
    return 0;
}

