#include <iostream>
#include <string>
#include <cstring>
using namespace std;
string s;
long long memo[20][170];
int S;
long long f(int p, int sum, bool strans) {
    if (sum > S) return 0;
    if (p == (int)s.size()) return sum == S;
    if (!strans && memo[p][sum] != -1) return memo[p][sum];
    int lim = strans ? s[p] - '0' : 9;
    long long r = 0;
    for (int c = 0; c <= lim; c++) r += f(p + 1, sum + c, strans && c == lim);
    if (!strans) memo[p][sum] = r;
    return r;
}
int main() {
    cin >> s >> S;
    memset(memo, -1, sizeof memo);
    cout << f(0, 0, true);
    return 0;
}

