    long long d = euclid(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return d;
}
int main() {
    long long a, b, c, x, y;
    cin >> a >> b >> c;
    long long d = euclid(a, b, x, y);
    if (c % d != 0) {
        cout << "NU";
        return 0;
    }
    long long m = b / d;
    long long x0 = (__int128)x * (c / d) % m;
    if (x0 < 0) x0 += m;
    cout << x0 << " " << (c - a * x0) / b;
    return 0;
}

