#include <iostream>
using namespace std;
int cifreComune(long long a, long long b) {
    int v[10] = {0}, c = 0;
    do {
        v[a % 10] = 1;
        a /= 10;
    } while (a > 0);
    do {
        if (v[b % 10] == 1) {
            v[b % 10] = 2;
            c++;
        }
        b /= 10;
    } while (b > 0);
    return c;
}
int main() {
    int n, best = 0;
    long long x, ant;
    cin >> n >> ant;
    for (int i = 1; i < n; i++) {
        cin >> x;
        int k = cifreComune(ant, x);
        if (k > best) best = k;
        ant = x;
    }
    cout << best;
    return 0;
}
